        nMinionClassId = 0;
        eUnitType = UNIT_MONSTER;
        nOwnerGUID = D2Client::UNIT::GetGUID(pUnit);
        Ai::AiGeneral::AssignMinionOwner(pGameInst, pSpawnedMinion, nOwnerGUID, eUnitType, nMinionClassId, bMinionIsLeader);
